if (cmd) for (const c of cmd) { const a=c.Args||""; if (!a || !sysrx.test(a) || /powershell|cmd\.exe|rundll32|regsvr32|wmic|psexec|mimikatz|net\.exe|net1|schtasks|certutil|bitsadmin|nltest|whoami|tasklist|cscript|wscript|-enc|invoke|downloadstring|\.ps1|\.bat|\.vbs|temp\\|\\users\\|appdata|public\\/i.test(a)) log(`${c.PID}\t${c.Process}\t${a.slice(0,180)}`); }
log("\n=== NETSCAN foreign ===");
if (net) for (const n of net) { const fa=n.ForeignAddr||""; if (fa && fa!="*" && fa!="0.0.0.0" && fa!="::" && fa!="::1" && !fa.startsWith("127.")) log(`${n.Proto}\t${n.LocalAddr}:${n.LocalPort} -> ${fa}:${n.ForeignPort}\t${n.State||""}\tPID=${n.PID||n.Pid||""}\t${n.Owner||""}\t${n.Created||""}`); }
log("\n=== CONSOLES (n="+(con?con.length:0)+") ===");
if (con) for (const c of con) { log(`[${c.Process} pid=${c.PID} cmd=${c.Cmd}]`); if (c.Data) log(c.Data.slice(0,2000)); }

async function triage(label, img) {
  const [cmd, net, con] = await Promise.all([
    MemoryAnalysisToolkit.WindowsCmdLineAsync(img),
    MemoryAnalysisToolkit.WindowsNetScanAsync(img),
    MemoryAnalysisToolkit.WindowsConsolesAsync(img)
  ]);
  log("################ "+label+" ################");
  const sus=/temp\\|\\users\\|appdata|public\\|perfmon|\.ps1|\.bat|\.vbs|-enc| -e |powershell|rundll32|regsvr32|wmic|psexec|mimikatz|schtasks|certutil|bitsadmin|nltest|whoami|cscript|wscript|\\windows\\[a-z_]+\.exe |invoke|downloadstring|net1 |net use|net group|net localgroup/i;
  log("-- CMDLINE n="+(cmd?cmd.length:0)+" (filtered) --");
  if (cmd) for (const c of cmd) { const a=c.Args||""; if (sus.test(a) || sus.test(c.Process||"")) log(`${c.PID}\t${c.Process}\t${a.slice(0,170)}`); }
  log("-- NETSCAN foreign --");
  if (net) for (const n of net) { const fa=n.ForeignAddr||""; if (fa && fa!="*"&&fa!="0.0.0.0"&&fa!="::"&&fa!="::1"&&!fa.startsWith("127.")) log(`${n.Proto}\t${n.LocalAddr}:${n.LocalPort} -> ${fa}:${n.ForeignPort}\t${n.State||""}`); }
  log("-- CONSOLES n="+(con?con.length:0)+" --");
  if (con) for (const c of con) { log(`[${c.Process} cmd=${c.Cmd}]`); if (c.Data) log(c.Data.slice(0,1800)); }
}
await triage("RD-02", "/mnt/artifacts/srl-2018/base-rd-02-memory.img");
await triage("FILE", "/home/sansforensics/artifacts/srl2018/base-file-memory.img");

