const dc = "/mnt/artifacts/srl-2018/base-dc-memory.img";
const [dps, dnet, dcmd] = await Promise.all([
  MemoryAnalysisToolkit.WindowsPsScanAsync(dc),
  MemoryAnalysisToolkit.WindowsNetScanAsync(dc),
  MemoryAnalysisToolkit.WindowsCmdLineAsync(dc)
