log("== DC psscan n="+(dps?dps.length:"null")+"  cmdline n="+(dcmd?dcmd.length:"null")+"  netscan n="+(dnet?dnet.length:"null"));
log("-- DC netscan foreign --");
if (dnet) for (const n of dnet) { const fa=n.ForeignAddr||""; if (fa && fa!="*"&&fa!="0.0.0.0"&&fa!="::"&&fa!="::1"&&!fa.startsWith("127.")) log(`${n.Proto}\t${n.LocalAddr}:${n.LocalPort} -> ${fa}:${n.ForeignPort}\t${n.State||""}`); }
