const roguerx=/^p\.exe|perfmon|\bcmd\.exe|powershell|psexec|mimikat|wce|procdump|rundll32|nc\.exe|^[a-z]\.exe$|gsecdump|fgdump/i;
function flagps(label, arr){ log("-- "+label+" suspicious psscan --"); if(!arr){log("null");return;} const seen={}; for(const p of arr){ const n=(p.ImageFileName||""); if(roguerx.test(n)){ const k=n+"|"+p.PID; if(!seen[k]){seen[k]=1; log(`${p.PID}\t${p.PPID}\t${n}\t${p.CreateTime||""}`);} } } }
