if (Session["mounts"]===undefined) Session["mounts"]={};
for (const [h,p] of Object.entries(disks)) {
  const m = await DiskAnalysisWorkflow.MountEwfImageAsync(p, "/mnt/case_"+h);
  if (!m.IsSuccess) { log(`${h}: mount EWF failed: ${m.Message}`); continue; }
