  Session["mounts"][h] = { ewf: m.Result, fs: null };
}
log("mounted ewf for: "+Object.keys(Session["mounts"]).join(","));

const ms = Session["mounts"];
for (const h of Object.keys(ms)) {
  if (ms[h].fs) { log(`${h}: already fs-mounted at ${ms[h].fs.MountDir}`); continue; }
  const r = await DiskAnalysisWorkflow.MountFileSystemAsync(ms[h].ewf, 0, "/mnt/casefs_"+h);
  if (!r.IsSuccess) { log(`${h}: fs mount failed: ${r.Message}`); continue; }
  ms[h].fs = r.Result;
  log(`${h}: mounted at ${r.Result.MountDir}  fstype=${r.Result.Info?r.Result.Info.FileSystemType:"?"}`);
}
Session["mounts"]=ms;
// quick sanity: list top-level + Users on each
for (const h of Object.keys(ms)) {
  if (!ms[h].fs) continue;
  const users = await DiskAnalysisToolkit.FindFilesAsync(ms[h].fs.MountDir+"/Users", "*", 1);
  log(`${h} Users: ` + (users?users.map(u=>u.Name||u.Path).filter(Boolean).slice(0,40).join(", "):"null"));
}

const ms = Session["mounts"];
for (const h of Object.keys(ms)) {
  const root = ms[h].fs.MountDir;
  const ntu = await DiskAnalysisToolkit.FindFilesAsync(root+"/Users", "NTUSER.DAT", 2);
  const users = ntu? ntu.map(f=>(f.Path||"").replace(/\\/g,"/").split("/Users/")[1]).map(s=>s?s.split("/")[0]:"").filter(Boolean) : [];
