const evt = await DiskAnalysisToolkit.FindFilesAsync(dcroot+"/Windows/System32/winevt/Logs", ["Security.evtx","System.evtx","Microsoft-Windows-PowerShell%4Operational.evtx","Microsoft-Windows-Sysmon%4Operational.evtx"], 1);
