const ms = Session["mounts"];
const watch = ["mimikatz","psexec","procdump","wce","gsecdump","fgdump","cobalt","beacon","ncat","plink","csvde","ntdsutil","secretsdump"];
const frags = ["\\temp\\","\\perflogs\\","\\public\\","perfmon"];
