const psvc = Session["mounts"].file.fs.MountDir+"/Windows/Temp/perfmon/PerfSvc.exe";
for (const [label,f] of [["rd01:p.exe",pexe],["file:PerfSvc.exe",psvc]]) {
  log("### "+label);
  const m = await YaraToolkit.ScanAsync("/opt/yara-rules/malware_index.yar", f, { Timeout: 120 });
  if (m && m.length) for (const x of m) log("  YARA: "+(x.Rule||x.RuleName||JSON.stringify(x)).toString().slice(0,120));
  else log("  YARA malware_index: no match (n="+(m?m.length:"null")+")");
}

const pexe = Session["mounts"].rd01.fs.MountDir+"/Windows/Temp/Perfmon/p.exe";
const psvc = Session["mounts"].file.fs.MountDir+"/Windows/Temp/perfmon/PerfSvc.exe";
const ind = ["172.16.4.10","squirrel","8080","http://","https://","mimikatz","sekurlsa","lsass","\\\\.\\pipe","cmd.exe","powershell","beacon","ReflectiveLoader","meterpreter","\\.exe","DOMAIN","carbon","SHIELD","\\Temp\\"];
for (const [label,f] of [["rd01:p.exe",pexe],["file:PerfSvc.exe",psvc]]) {
