for (const label of ["rd01_p_exe","file_PerfSvc_exe"]) {
  const out = "/tmp/strings_"+label+".txt";
  log("### "+label+" (ASCII >=6) sample:");
  const a = await DiskAnalysisToolkit.GrepLinesAsync(out, ["[ -~]{8,}"], false, 45);
  if (a) for (const l of a.slice(0,45)) log("  "+l.slice(0,120));
  log("### "+label+" (UTF16) sample:");
  const u = await DiskAnalysisToolkit.GrepLinesAsync(out+".u", ["[ -~]{8,}"], false, 30);
  if (u) for (const l of u.slice(0,30)) log("  "+l.slice(0,120));
}

auditFinding(
 "Disk-recovered binaries: rd-01 C:\\Windows\\Temp\\Perfmon\\p.exe (164352 bytes, SHA256 7fa4f6cc4e1bb27da7d9af7a2a533e72751b025b063e1df4359ebe127fd2892c) is UPX-packed (YARA: UPX, suspicious_packer_section) and its strings include the named-pipe token 'MSSE-%d-'. file server C:\\Windows\\Temp\\perfmon\\PerfSvc.exe (18944 bytes, SHA256 e722dd429510c83485bb276c559015df9bd4931e7e4339eb90683cc3efd9beaa) is a Windows service stub (StartServiceCtrlDispatcherA, RegisterServiceCtrlHandlerA, SetServiceStatus) that calls CreateNamedPipeA for pipe 'MSSE-%d-server', CreateProcessA, and references rundll32.exe / '%s\\System32\\%s' / DceRpcSs.",
 "The attacker's implant is a Cobalt-Strike-style SMB/named-pipe beacon. PerfSvc.exe is the service-based (PsExec/SMB-beacon) variant providing execution+persistence; p.exe is the packed beacon. The 'MSSE-<n>-server' named pipe and rundll32 spawning match the Cobalt Strike (Metasploit-derived) SMB beacon, corroborated by the file server's powershell-spawning-many-rundll32 process pattern seen in memory.",
 "HIGH",
 "93f4b2fb, 48d19cb2, 421294a8, 4ba65cc1");
auditReviewRec("Malware-family attribution: the MSSE-<n>-server named pipe + service stub + rundll32 post-ex is canonical Cobalt Strike / Metasploit-derived SMB beacon. Attribution to the Cobalt Strike framework specifically is high-likelihood but circumstantial (no config/beacon-config extracted); alternative is a Metasploit service payload. Recorded for reviewer judgement.");
log("recorded malware family");

const ms = Session["mounts"];
const frags = ["\\temp\\","perfmon","\\public\\","\\programdata\\","powershell -","-enc","-w hidden","rundll32","\\users\\public"];
for (const h of Object.keys(ms)) {
  const root = ms[h].fs.MountDir;
  const r = await WindowsAnalysisWorkflow.FindRegistryPersistenceMechanismsAsync(
    root+"/Windows/System32/config/SOFTWARE",
    root+"/Windows/System32/config/SYSTEM",
    null,
    root+"/Windows/System32/Tasks",
    frags);
  if (!r.IsSuccess) { log(`### ${h}: FAILED ${r.Message}`); continue; }
  const susp = r.Result.SuspiciousEntries||[];
  log(`### ${h}: mechanisms=${(r.Result.Mechanisms||[]).length} all=${(r.Result.AllEntries||[]).length} SUSPICIOUS=${susp.length}`);
  for (const e of susp) log(`  [${e.Type}] ${e.Name}\t${(e.Command||"").slice(0,110)}\t${(e.Reasons||[]).join("|")}`);
}

const ms = Session["mounts"];
// 1) read 1.bat on rd-01 (and look for it on others)
for (const h of Object.keys(ms)) {
  const bats = await DiskAnalysisToolkit.FindFilesAsync(ms[h].fs.MountDir+"/Windows/Temp", ["*.bat","*.ps1","*.vbs"], 1);
