const ost = Session["mounts"].rd02.fs.MountDir+"/Users/kellee.espinoza/AppData/Local/Microsoft/Outlook/outlook.ost";
const r = await WindowsAnalysisToolkit.ReadPstAsync(ost, 4000);
const msgs = r.Messages||[];
const risky=/\.(docm|dotm|xlsm|js|jse|vbs|vba|wsf|hta|lnk|scr|exe|iso|img|ace|cab|zip|rar|7z|ps1|jar)$/i;
let shown=0;
for (const m of msgs) {
  const atts=m.AttachmentNames||[];
  if (!atts.length) continue;
  const hit=atts.some(a=>risky.test(a));
  if (hit) { if(shown++>=40){log("...more");break;} log(`${m.Date}\t${(m.From||"").slice(0,40)}\tsrcIp=${m.SourceIp||""}\t${(m.Subject||"").slice(0,40)}\tATT:[${atts.join("; ").slice(0,100)}]`); }
}
log("risky-attachment messages="+shown);
// also: any message mentioning squirreldirectory or carbonadium in subject
let kw=0;
for (const m of msgs){ if(/squirrel|carbonadium|invoice|\.zip|\.docm|patch|update your|verify/i.test(m.Subject||"")){ if(kw++<15) log("KW: "+m.Date+"  "+(m.From||"").slice(0,35)+"  "+(m.Subject||"").slice(0,60)); } }
log("keyword-subject="+kw);

auditMissingEvidence("No phishing/malspam email found in the available mailboxes (rd-02 kellee.espinoza outlook.ost = 1592 msgs, jpallen tiny): all internal stark-research-labs.com/shieldbase.lan traffic with random-word subjects (SANS Lariat-generated filler), no risky attachments (docm/js/hta/lnk/zip/exe) and no external sender domains. The earliest attacker source host 172.16.6.14 (BASE-RD-04) was not imaged (no disk or memory). Therefore the initial-access vector cannot be confirmed from available evidence.");
auditReviewRec("System Zero / initial access (under-determined): earliest attacker activity observed is RDP/network logons originating from 172.16.6.14 (BASE-RD-04, an RDS host) using valid domain accounts nromanoff then spsql, starting 2018-08-23. BASE-RD-04 is the most likely patient-zero in our visibility but was NOT imaged. The use of a SQL *service* account (spsql) for interactive RDP indicates prior credential theft (candidates: Kerberoasting of the spsql SPN with offline cracking, or LSASS/mimikatz harvesting on an early host). Initial delivery (phishing vs valid-account/RDP access vs exploitation) is unconfirmed. Candidates presented; no single vector proven.");
// DC skeleton key / golden ticket indicators in memory
const dc="/mnt/artifacts/srl-2018/base-dc-memory.img";
const sk = await MemoryAnalysisWorkflow.DetectSkeletonKeyAsync(dc);
log("DC DetectSkeletonKey: "+sk.IsSuccess+" :: "+(sk.Message||"").slice(0,260));
if (sk.IsSuccess && sk.Result) log("  "+JSON.stringify(sk.Result).slice(0,300));
log("recorded initial-access assessment");

const ms=Session["mounts"];
for (const h of ["rd02","file"]) {
  const root=ms[h].fs.MountDir;
  const lc = await WindowsAnalysisWorkflow.DetectLogClearingAsync(root+"/Windows/System32/winevt/Logs/Security.evtx", root+"/Windows/System32/winevt/Logs/System.evtx");
  log(`### ${h} logclear detected=${lc.IsSuccess?lc.Result.Detected:"FAIL"}`);
  if (lc.IsSuccess) for (const e of (lc.Result.Events||[])) log(`  ${e.Time}\tEID${e.EventId}\t${e.ClearedLog}\t${e.User}\t${e.Computer}`);
}
auditFinding(
 "Anti-forensics observations: (a) attacker tools deleted from disk - p.exe/pa.exe/pb.exe/ri.exe/sd.exe/csrss.exe survive only in Shimcache; 1.bat (scheduled-task payload) deleted; the staged Research\\Carbon corpus deleted (recovered from spsql Recycle Bin). (b) Masquerading: implant named csrss.exe (a real system process), service-looking PerfSvc.exe, staging dir C:\\Windows\\Temp\\perfmon, scheduled task 'Collect Background Statistics'. (c) DetectLogClearing: incident-window (Aug-Sep 2018) Security/System log clears NOT found on DC/rd-01/rd-02/file; the only 1102/104 clears are 2018-05-04 by WIN10-TEST\\Administrator (gold-image build). DC DetectSkeletonKey: no implant (IsCompromised=false).",
 "The attacker's anti-forensics were primarily file deletion (tools + staged data) and name-masquerading rather than event-log clearing - the Windows event logs were left intact in the incident window, which is why the activity is so well reconstructable. No skeleton-key/DC auth-bypass implant was planted (the ntds.dit dump instead enables offline credential/golden-ticket abuse).",
 "MEDIUM",
 "455f2ca5, f9de58df, c9bcf643, d5ecce5c");
